scripts.build:invoice:
cd Invoice/server && npm install --no-audit --no-fund && mkdir -p node_modules/@prisma/client && printf 'export const UserRole = { ADMIN: "ADMIN", FINANCE_MANAGER: "FINANCE_MANAGER", ACCOUNTANT: "ACCOUNTANT", SALES: "SALES" };
export const InvoiceStatus = { DRAFT: "DRAFT", PENDING_APPROVAL: "PENDING_APPROVAL", APPROVED: "APPROVED", ISSUED: "ISSUED", PARTIALLY_PAID: "PARTIALLY_PAID", PAID: "PAID", CANCELLED: "CANCELLED" };
export const ApprovalStatus = { PENDING: "PENDING", APPROVED: "APPROVED", REJECTED: "REJECTED" };
export const PaymentMethod = { BANK_TRANSFER: "BANK_TRANSFER", CASH: "CASH", CHEQUE: "CHEQUE", ONLINE: "ONLINE" };
export const DeliveryChannel = { PDF: "PDF", EMAIL: "EMAIL", WHATSAPP: "WHATSAPP" };
export const DeliveryStatus = { PENDING: "PENDING", SUCCESS: "SUCCESS", FAILED: "FAILED" };
export class PrismaClient {}
export const Prisma: any = {};
' > node_modules/@prisma/client/index.js && printf 'export type UserRole = "ADMIN" | "FINANCE_MANAGER" | "ACCOUNTANT" | "SALES";
export type InvoiceStatus = "DRAFT" | "PENDING_APPROVAL" | "APPROVED" | "ISSUED" | "PARTIALLY_PAID" | "PAID" | "CANCELLED";
export type ApprovalStatus = "PENDING" | "APPROVED" | "REJECTED";
export type PaymentMethod = "BANK_TRANSFER" | "CASH" | "CHEQUE" | "ONLINE";
export type DeliveryChannel = "PDF" | "EMAIL" | "WHATSAPP";
export type DeliveryStatus = "PENDING" | "SUCCESS" | "FAILED";
export declare const UserRole: Record<UserRole, UserRole>;
export declare const InvoiceStatus: Record<InvoiceStatus, InvoiceStatus>;
export declare const ApprovalStatus: Record<ApprovalStatus, ApprovalStatus>;
export declare const PaymentMethod: Record<PaymentMethod, PaymentMethod>;
export declare const DeliveryChannel: Record<DeliveryChannel, DeliveryChannel>;
export declare const DeliveryStatus: Record<DeliveryStatus, DeliveryStatus>;
export declare class PrismaClient { [key: string]: any; }
export declare namespace Prisma { export type Decimal = any; export type InputJsonValue = any; [key: string]: any; }
' > node_modules/@prisma/client/index.d.ts && printf '{"name":"@prisma/client","main":"index.js","types":"index.d.ts"}' > node_modules/@prisma/client/package.json && node ./node_modules/typescript/bin/tsc && cd ../.. && rm -rf Invoice/client media admin *.bat *.md
